   '{"sections": [{"code": "numerical", "name": "Numbers", "time_limit_sec": 300, "items": [{"id": "apt_num1", "type": "mcq", "prompt": "A shirt costs ₹800 after a 20% discount. What was the price before the discount?", "scale": "numerical", "key": 1, "options": [{"value": 0, "label": "₹640"}, {"value": 1, "label": "₹1,000"}, {"value": 2, "label": "₹960"}, {"value": 3, "label": "₹1,200"}]}, {"id": "apt_num2", "type": "mcq", "prompt": "A train covers 150 km in 2.5 hours. What is its average speed?", "scale": "numerical", "key": 3, "options": [{"value": 0, "label": "66 km/h"}, {"value": 1, "label": "50 km/h"}, {"value": 2, "label": "48 km/h"}, {"value": 3, "label": "60 km/h"}]}, {"id": "apt_num3", "type": "mcq", "prompt": "What is the simple interest on ₹8,000 at 5% a year for 3 years?", "scale": "numerical", "key": 3, "options": [{"value": 0, "label": "₹400"}, {"value": 1, "label": "₹1,600"}, {"value": 2, "label": "₹9,200"}, {"value": 3, "label": "₹1,200"}]}, {"id": "apt_num4", "type": "mcq", "prompt": "What is 12% of 250 plus 25% of 120?", "scale": "numerical", "key": 0, "options": [{"value": 0, "label": "60"}, {"value": 1, "label": "66"}, {"value": 2, "label": "54"}, {"value": 3, "label": "72"}]}, {"id": "apt_num5", "type": "mcq", "prompt": "₹500 is shared between Asha and Ben in the ratio 2:3. How much does Ben get?", "scale": "numerical", "key": 2, "options": [{"value": 0, "label": "₹250"}, {"value": 1, "label": "₹200"}, {"value": 2, "label": "₹300"}, {"value": 3, "label": "₹350"}]}, {"id": "apt_num6", "type": "mcq", "prompt": "A can finish a job in 6 days and B in 12 days. How long do they take working together?", "scale": "numerical", "key": 3, "options": [{"value": 0, "label": "9 days"}, {"value": 1, "label": "5 days"}, {"value": 2, "label": "18 days"}, {"value": 3, "label": "4 days"}]}, {"id": "apt_num7", "type": "mcq", "prompt": "An item bought for ₹400 is sold for ₹500. What is the profit percentage?", "scale": "numerical", "key": 2, "options": [{"value": 0, "label": "30%"}, {"value": 1, "label": "20%"}, {"value": 2, "label": "25%"}, {"value": 3, "label": "15%"}]}, {"id": "apt_num8", "type": "mcq", "prompt": "Marks in four tests are 62, 74, 81, 71. What is the average?", "scale": "numerical", "key": 0, "options": [{"value": 0, "label": "72"}, {"value": 1, "label": "72.3"}, {"value": 2, "label": "70"}, {"value": 3, "label": "74"}]}]}, {"code": "verbal", "name": "Words", "time_limit_sec": 300, "items": [{"id": "apt_ver1", "type": "mcq", "prompt": "Choose the word closest in meaning to METICULOUS.", "scale": "verbal", "key": 1, "options": [{"value": 0, "label": "Loud"}, {"value": 1, "label": "Precise"}, {"value": 2, "label": "Quick"}, {"value": 3, "label": "Careless"}]}, {"id": "apt_ver2", "type": "mcq", "prompt": "BOOK is to READ as FORK is to …", "scale": "verbal", "key": 2, "options": [{"value": 0, "label": "Kitchen"}, {"value": 1, "label": "Metal"}, {"value": 2, "label": "Eat"}, {"value": 3, "label": "Spoon"}]}, {"id": "apt_ver3", "type": "mcq", "prompt": "Choose the word opposite in meaning to SCARCE.", "scale": "verbal", "key": 3, "options": [{"value": 0, "label": "Hidden"}, {"value": 1, "label": "Rare"}, {"value": 2, "label": "Small"}, {"value": 3, "label": "Plentiful"}]}, {"id": "apt_ver4", "type": "mcq", "prompt": "Which sentence is correct?", "scale": "verbal", "key": 2, "options": [{"value": 0, "label": "Each of the student have a book."}, {"value": 1, "label": "Each of the students have a book."}, {"value": 2, "label": "Each of the students has a book."}, {"value": 3, "label": "Each students has a book."}]}, {"id": "apt_ver5", "type": "mcq", "prompt": "Choose the word closest in meaning to CANDID.", "scale": "verbal", "key": 3, "options": [{"value": 0, "label": "Sweet"}, {"value": 1, "label": "Careful"}, {"value": 2, "label": "Secretive"}, {"value": 3, "label": "Frank"}]}, {"id": "apt_ver6", "type": "mcq", "prompt": "Choose the word opposite in meaning to EXPAND.", "scale": "verbal", "key": 0, "options": [{"value": 0, "label": "Contract"}, {"value": 1, "label": "Grow"}, {"value": 2, "label": "Widen"}, {"value": 3, "label": "Extend"}]}, {"id": "apt_ver7", "type": "mcq", "prompt": "DOCTOR is to HOSPITAL as TEACHER is to …", "scale": "verbal", "key": 0, "options": [{"value": 0, "label": "School"}, {"value": 1, "label": "Lesson"}, {"value": 2, "label": "Book"}, {"value": 3, "label": "Student"}]}, {"id": "apt_ver8", "type": "mcq", "prompt": "''Most students who revised daily scored above 70.'' Which statement is best supported?", "scale": "verbal", "key": 3, "options": [{"value": 0, "label": "Revision has no effect on scores"}, {"value": 1, "label": "Students who did not revise failed"}, {"value": 2, "label": "Every student who revised daily scored above 70"}, {"value": 3, "label": "Daily revision went with higher scores for most of these students"}]}]}, {"code": "abstract", "name": "Patterns", "time_limit_sec": 300, "items": [{"id": "apt_abs1", "type": "mcq", "prompt": "What comes next: 1, 3, 7, 13, 21, …", "scale": "abstract", "key": 3, "options": [{"value": 0, "label": "32"}, {"value": 1, "label": "41"}, {"value": 2, "label": "30"}, {"value": 3, "label": "31"}]}, {"id": "apt_abs2", "type": "mcq", "prompt": "What comes next: 3, 9, 27, 81, 243, …", "scale": "abstract", "key": 0, "options": [{"value": 0, "label": "729"}, {"value": 1, "label": "1215"}, {"value": 2, "label": "730"}, {"value": 3, "label": "728"}]}, {"id": "apt_abs3", "type": "mcq", "prompt": "What comes next: 9, 16, 25, 36, 49, …", "scale": "abstract", "key": 0, "options": [{"value": 0, "label": "64"}, {"value": 1, "label": "63"}, {"value": 2, "label": "65"}, {"value": 3, "label": "79"}]}, {"id": "apt_abs4", "type": "mcq", "prompt": "What comes next: C, F, I, L, O, …", "scale": "abstract", "key": 2, "options": [{"value": 0, "label": "Q"}, {"value": 1, "label": "T"}, {"value": 2, "label": "R"}, {"value": 3, "label": "S"}]}, {"id": "apt_abs5", "type": "mcq", "prompt": "What comes next: 2, 2, 4, 6, 10, …", "scale": "abstract", "key": 3, "options": [{"value": 0, "label": "15"}, {"value": 1, "label": "22"}, {"value": 2, "label": "17"}, {"value": 3, "label": "16"}]}, {"id": "apt_abs6", "type": "mcq", "prompt": "What comes next: 16, 21, 20, 25, 24, …", "scale": "abstract", "key": 2, "options": [{"value": 0, "label": "34"}, {"value": 1, "label": "28"}, {"value": 2, "label": "29"}, {"value": 3, "label": "30"}]}, {"id": "apt_abs7", "type": "mcq", "prompt": "What comes next: 1, 3, 7, 15, 31, …", "scale": "abstract", "key": 1, "options": [{"value": 0, "label": "62"}, {"value": 1, "label": "63"}, {"value": 2, "label": "64"}, {"value": 3, "label": "95"}]}, {"id": "apt_abs8", "type": "mcq", "prompt": "Which number does not belong: 121, 144, 169, 196, 210?", "scale": "abstract", "key": 0, "options": [{"value": 0, "label": "210"}, {"value": 1, "label": "196"}, {"value": 2, "label": "144"}, {"value": 3, "label": "169"}]}]}, {"code": "spatial", "name": "Shapes and space", "time_limit_sec": 300, "items": [{"id": "apt_spa1", "type": "mcq", "prompt": "A cube painted on all faces is cut into 27 equal small cubes. How many small cubes have exactly two painted faces?", "scale": "spatial", "key": 0, "options": [{"value": 0, "label": "12"}, {"value": 1, "label": "8"}, {"value": 2, "label": "6"}, {"value": 3, "label": "18"}]}, {"id": "apt_spa2", "type": "mcq", "prompt": "The same 27 small cubes: how many have no painted face?", "scale": "spatial", "key": 2, "options": [{"value": 0, "label": "6"}, {"value": 1, "label": "8"}, {"value": 2, "label": "1"}, {"value": 3, "label": "0"}]}, {"id": "apt_spa3", "type": "mcq", "prompt": "You face north, turn 90° right, then turn 180°. Which way are you facing?", "scale": "spatial", "key": 0, "options": [{"value": 0, "label": "West"}, {"value": 1, "label": "North"}, {"value": 2, "label": "East"}, {"value": 3, "label": "South"}]}, {"id": "apt_spa4", "type": "mcq", "prompt": "Opposite faces of a standard die add up to 7. If the top shows 2, what is on the bottom?", "scale": "spatial", "key": 1, "options": [{"value": 0, "label": "6"}, {"value": 1, "label": "5"}, {"value": 2, "label": "4"}, {"value": 3, "label": "3"}]}, {"id": "apt_spa5", "type": "mcq", "prompt": "A clock shows 3:00. What time does its mirror image show?", "scale": "spatial", "key": 1, "options": [{"value": 0, "label": "6:00"}, {"value": 1, "label": "9:00"}, {"value": 2, "label": "3:00"}, {"value": 3, "label": "12:00"}]}, {"id": "apt_spa6", "type": "mcq", "prompt": "What is the angle between the hour and minute hands at 3:00?", "scale": "spatial", "key": 1, "options": [{"value": 0, "label": "45°"}, {"value": 1, "label": "90°"}, {"value": 2, "label": "120°"}, {"value": 3, "label": "60°"}]}, {"id": "apt_spa7", "type": "mcq", "prompt": "How many faces does a hexagonal prism have?", "scale": "spatial", "key": 2, "options": [{"value": 0, "label": "6"}, {"value": 1, "label": "7"}, {"value": 2, "label": "8"}, {"value": 3, "label": "12"}]}, {"id": "apt_spa8", "type": "mcq", "prompt": "A sheet is folded in half three times and one hole is punched through all layers. How many holes appear when it is opened?", "scale": "spatial", "key": 2, "options": [{"value": 0, "label": "6"}, {"value": 1, "label": "3"}, {"value": 2, "label": "8"}, {"value": 3, "label": "9"}]}]}, {"code": "mechanical", "name": "How things work", "time_limit_sec": 300, "items": [{"id": "apt_mec1", "type": "mcq", "prompt": "Three gears are in a line, each touching the next. The first turns clockwise. Which way does the third turn?", "scale": "mechanical", "key": 1, "options": [{"value": 0, "label": "It depends on its size"}, {"value": 1, "label": "Clockwise"}, {"value": 2, "label": "Anticlockwise"}, {"value": 3, "label": "It does not turn"}]}, {"id": "apt_mec2", "type": "mcq", "prompt": "To lift a heavy rock with a crowbar using the least effort, where should the pivot go?", "scale": "mechanical", "key": 1, "options": [{"value": 0, "label": "Close to your hands"}, {"value": 1, "label": "Close to the rock"}, {"value": 2, "label": "Exactly in the middle"}, {"value": 3, "label": "It does not matter"}]}, {"id": "apt_mec3", "type": "mcq", "prompt": "A single movable pulley lifts a 100 N load. Ignoring friction, about how much effort is needed?", "scale": "mechanical", "key": 0, "options": [{"value": 0, "label": "50 N"}, {"value": 1, "label": "100 N"}, {"value": 2, "label": "200 N"}, {"value": 3, "label": "25 N"}]}, {"id": "apt_mec4", "type": "mcq", "prompt": "A 40-tooth gear drives a 10-tooth gear. If the large gear makes 3 turns, how many does the small gear make?", "scale": "mechanical", "key": 2, "options": [{"value": 0, "label": "3"}, {"value": 1, "label": "7.5"}, {"value": 2, "label": "12"}, {"value": 3, "label": "4"}]}, {"id": "apt_mec5", "type": "mcq", "prompt": "Why does a sharp knife cut better than a blunt one?", "scale": "mechanical", "key": 2, "options": [{"value": 0, "label": "It is made of stronger metal"}, {"value": 1, "label": "It has more friction"}, {"value": 2, "label": "The same force acts on a smaller area, so the pressure is higher"}, {"value": 3, "label": "It is heavier"}]}, {"id": "apt_mec6", "type": "mcq", "prompt": "A small force on the small piston of a hydraulic jack lifts a car. Why?", "scale": "mechanical", "key": 2, "options": [{"value": 0, "label": "The liquid is lighter than air"}, {"value": 1, "label": "The small piston stores energy"}, {"value": 2, "label": "The liquid passes the pressure to a larger piston, which multiplies the force"}, {"value": 3, "label": "The car becomes lighter"}]}, {"id": "apt_mec7", "type": "mcq", "prompt": "Two pulleys are joined by a crossed belt. If one turns clockwise, the other turns …", "scale": "mechanical", "key": 0, "options": [{"value": 0, "label": "Anticlockwise"}, {"value": 1, "label": "Clockwise"}, {"value": 2, "label": "Not at all"}, {"value": 3, "label": "Clockwise but faster"}]}, {"id": "apt_mec8", "type": "mcq", "prompt": "A ball rolls off a table at the moment an identical ball is dropped from the same height. Ignoring air, which lands first?", "scale": "mechanical", "key": 2, "options": [{"value": 0, "label": "The rolling ball"}, {"value": 1, "label": "The dropped ball"}, {"value": 2, "label": "They land together"}, {"value": 3, "label": "It depends on the table"}]}]}, {"code": "perceptual", "name": "Speed and accuracy", "time_limit_sec": 180, "items": [{"id": "apt_per1", "type": "mcq", "prompt": "Which pair is exactly the same on both sides?", "scale": "perceptual", "key": 0, "options": [{"value": 0, "label": "EUZMC2D – EUZMC2D"}, {"value": 1, "label": "R6JGZUV – RVJGZUV"}, {"value": 2, "label": "AWYNAB8 – AWMNAB8"}, {"value": 3, "label": "9HG38NP – 9HG3UNP"}]}, {"id": "apt_per2", "type": "mcq", "prompt": "Which pair is exactly the same on both sides?", "scale": "perceptual", "key": 2, "options": [{"value": 0, "label": "3GT6XLJ – 3GTPXLJ"}, {"value": 1, "label": "2RTSWL7 – 2RTSWLN"}, {"value": 2, "label": "H8T7L59 – H8T7L59"}, {"value": 3, "label": "H2MEYRM – H2ME4RM"}]}, {"id": "apt_per3", "type": "mcq", "prompt": "Which pair is exactly the same on both sides?", "scale": "perceptual", "key": 3, "options": [{"value": 0, "label": "VBRRADL – VBRRUDL"}, {"value": 1, "label": "GC245S5 – GA245S5"}, {"value": 2, "label": "EW5QPUY – EW5QNUY"}, {"value": 3, "label": "CJVP3TF – CJVP3TF"}]}, {"id": "apt_per4", "type": "mcq", "prompt": "Which pair is exactly the same on both sides?", "scale": "perceptual", "key": 0, "options": [{"value": 0, "label": "ACSA53S – ACSA53S"}, {"value": 1, "label": "LET6VB7 – LET6KB7"}, {"value": 2, "label": "8QU2SKL – 8QU2SJL"}, {"value": 3, "label": "N6DTNWF – 76DTNWF"}]}, {"id": "apt_per5", "type": "mcq", "prompt": "Which pair is exactly the same on both sides?", "scale": "perceptual", "key": 1, "options": [{"value": 0, "label": "L79295N – L792954"}, {"value": 1, "label": "VU22PD8 – VU22PD8"}, {"value": 2, "label": "YPDNE29 – YPDNP29"}, {"value": 3, "label": "NGCMSJV – NGCMSQV"}]}, {"id": "apt_per6", "type": "mcq", "prompt": "How many times does the digit 3 appear in: 6881 7696 1411 4396 5361 2302", "scale": "perceptual", "key": 2, "options": [{"value": 0, "label": "4"}, {"value": 1, "label": "2"}, {"value": 2, "label": "3"}, {"value": 3, "label": "5"}]}, {"id": "apt_per7", "type": "mcq", "prompt": "How many times does the digit 9 appear in: 1545 2893 5538 7493 4350 9202", "scale": "perceptual", "key": 0, "options": [{"value": 0, "label": "3"}, {"value": 1, "label": "5"}, {"value": 2, "label": "2"}, {"value": 3, "label": "4"}]}, {"id": "apt_per8", "type": "mcq", "prompt": "How many times does the digit 0 appear in: 7323 0728 1491 1915 0361 6903", "scale": "perceptual", "key": 1, "options": [{"value": 0, "label": "5"}, {"value": 1, "label": "3"}, {"value": 2, "label": "2"}, {"value": 3, "label": "4"}]}]}, {"code": "logical", "name": "Reasoning", "time_limit_sec": 300, "items": [{"id": "apt_log1", "type": "mcq", "prompt": "All roses are flowers. Some flowers fade quickly. Which must be true?", "scale": "logical", "key": 2, "options": [{"value": 0, "label": "All roses fade quickly"}, {"value": 1, "label": "Some roses fade quickly"}, {"value": 2, "label": "None of these must be true"}, {"value": 3, "label": "No rose fades quickly"}]}, {"id": "apt_log2", "type": "mcq", "prompt": "A is B''s brother. B is C''s mother. How is A related to C?", "scale": "logical", "key": 2, "options": [{"value": 0, "label": "Cousin"}, {"value": 1, "label": "Brother"}, {"value": 2, "label": "Uncle"}, {"value": 3, "label": "Father"}]}, {"id": "apt_log3", "type": "mcq", "prompt": "In a row, P is left of Q, Q is left of R, and S is right of R. Who is second from the left?", "scale": "logical", "key": 3, "options": [{"value": 0, "label": "P"}, {"value": 1, "label": "R"}, {"value": 2, "label": "S"}, {"value": 3, "label": "Q"}]}, {"id": "apt_log4", "type": "mcq", "prompt": "All Bloops are Razzies and all Razzies are Lazzies. So all Bloops are …", "scale": "logical", "key": 2, "options": [{"value": 0, "label": "not Lazzies"}, {"value": 1, "label": "only sometimes Lazzies"}, {"value": 2, "label": "Lazzies"}, {"value": 3, "label": "impossible to say"}]}, {"id": "apt_log5", "type": "mcq", "prompt": "''If it rains, the match is cancelled.'' The match was not cancelled. What follows?", "scale": "logical", "key": 1, "options": [{"value": 0, "label": "It rained"}, {"value": 1, "label": "It did not rain"}, {"value": 2, "label": "Nothing can be concluded"}, {"value": 3, "label": "The match was played indoors"}]}, {"id": "apt_log6", "type": "mcq", "prompt": "Today is Wednesday. What day will it be 10 days from now?", "scale": "logical", "key": 3, "options": [{"value": 0, "label": "Thursday"}, {"value": 1, "label": "Sunday"}, {"value": 2, "label": "Friday"}, {"value": 3, "label": "Saturday"}]}, {"id": "apt_log7", "type": "mcq", "prompt": "Ravi is taller than Sita. Sita is taller than Amit. Who is the shortest?", "scale": "logical", "key": 3, "options": [{"value": 0, "label": "Ravi"}, {"value": 1, "label": "Cannot tell"}, {"value": 2, "label": "Sita"}, {"value": 3, "label": "Amit"}]}, {"id": "apt_log8", "type": "mcq", "prompt": "Task B must come after A, C after B, and D before A. Which task comes first?", "scale": "logical", "key": 0, "options": [{"value": 0, "label": "D"}, {"value": 1, "label": "B"}, {"value": 2, "label": "C"}, {"value": 3, "label": "A"}]}]}]}'::jsonb,
   '{"method": "aptitude", "subtests": ["numerical", "verbal", "abstract", "spatial", "mechanical", "perceptual", "logical"], "bands": [[0, 25, "Low"], [25, 75, "Average"], [75, 90, "High"], [90, 101, "Very High"]]}'::jsonb,
