   '{"sections": [{"code": "numerical", "name": "Numbers", "time_limit_sec": 240, "items": [{"id": "apt_num1", "type": "mcq", "prompt": "Revenue of ₹80 lakh grows 10% a year for two years. What is it after two years?", "scale": "numerical", "key": 1, "options": [{"value": 0, "label": "₹96 lakh"}, {"value": 1, "label": "₹96.8 lakh"}, {"value": 2, "label": "₹97.8 lakh"}, {"value": 3, "label": "₹88 lakh"}]}, {"id": "apt_num2", "type": "mcq", "prompt": "Sales rise 10% in one quarter and fall 10% the next. Compared with the start, sales are …", "scale": "numerical", "key": 1, "options": [{"value": 0, "label": "The same"}, {"value": 1, "label": "1% lower"}, {"value": 2, "label": "10% lower"}, {"value": 3, "label": "1% higher"}]}, {"id": "apt_num3", "type": "mcq", "prompt": "Fixed costs are ₹90,000 a month and each unit earns ₹300 after variable costs. How many units must be sold to break even?", "scale": "numerical", "key": 3, "options": [{"value": 0, "label": "600"}, {"value": 1, "label": "400"}, {"value": 2, "label": "150"}, {"value": 3, "label": "300"}]}, {"id": "apt_num4", "type": "mcq", "prompt": "A team of 6 averages 40 tickets a day and a team of 4 averages 50. What is the combined average per person?", "scale": "numerical", "key": 3, "options": [{"value": 0, "label": "42"}, {"value": 1, "label": "46"}, {"value": 2, "label": "45"}, {"value": 3, "label": "44"}]}, {"id": "apt_num5", "type": "mcq", "prompt": "You drive to a site at 60 km/h and back by the same road at 40 km/h. What is the average speed for the round trip?", "scale": "numerical", "key": 1, "options": [{"value": 0, "label": "52 km/h"}, {"value": 1, "label": "48 km/h"}, {"value": 2, "label": "50 km/h"}, {"value": 3, "label": "45 km/h"}]}, {"id": "apt_num6", "type": "mcq", "prompt": "A product costs ₹1,600 to make and is priced with a 25% markup on cost. What is the price?", "scale": "numerical", "key": 2, "options": [{"value": 0, "label": "₹2,133"}, {"value": 1, "label": "₹1,625"}, {"value": 2, "label": "₹2,000"}, {"value": 3, "label": "₹1,200"}]}, {"id": "apt_num7", "type": "mcq", "prompt": "A ₹40 lakh budget includes ₹14 lakh for IT. What share of the budget is IT?", "scale": "numerical", "key": 3, "options": [{"value": 0, "label": "40%"}, {"value": 1, "label": "65%"}, {"value": 2, "label": "14%"}, {"value": 3, "label": "35%"}]}, {"id": "apt_num8", "type": "mcq", "prompt": "A metric moves from 50 to 58. What is the percentage increase?", "scale": "numerical", "key": 1, "options": [{"value": 0, "label": "13.8%"}, {"value": 1, "label": "16%"}, {"value": 2, "label": "21%"}, {"value": 3, "label": "8%"}]}]}, {"code": "verbal", "name": "Words", "time_limit_sec": 240, "items": [{"id": "apt_ver1", "type": "mcq", "prompt": "Choose the word closest in meaning to PRAGMATIC.", "scale": "verbal", "key": 3, "options": [{"value": 0, "label": "Stubborn"}, {"value": 1, "label": "Idealistic"}, {"value": 2, "label": "Talkative"}, {"value": 3, "label": "Practical"}]}, {"id": "apt_ver2", "type": "mcq", "prompt": "Choose the word opposite in meaning to TRANSPARENT.", "scale": "verbal", "key": 1, "options": [{"value": 0, "label": "Clear"}, {"value": 1, "label": "Opaque"}, {"value": 2, "label": "Thin"}, {"value": 3, "label": "Honest"}]}, {"id": "apt_ver3", "type": "mcq", "prompt": "AUTHOR is to NOVEL as COMPOSER is to …", "scale": "verbal", "key": 0, "options": [{"value": 0, "label": "Symphony"}, {"value": 1, "label": "Orchestra"}, {"value": 2, "label": "Piano"}, {"value": 3, "label": "Singer"}]}, {"id": "apt_ver4", "type": "mcq", "prompt": "Which sentence is correct?", "scale": "verbal", "key": 0, "options": [{"value": 0, "label": "Between you and me, the plan needs work."}, {"value": 1, "label": "Between you and I, the plan needs work."}, {"value": 2, "label": "Between yourself and I, the plan needs work."}, {"value": 3, "label": "Among you and I, the plan needs work."}]}, {"id": "apt_ver5", "type": "mcq", "prompt": "The report was so ___ that nobody could find the key point.", "scale": "verbal", "key": 2, "options": [{"value": 0, "label": "accurate"}, {"value": 1, "label": "brief"}, {"value": 2, "label": "verbose"}, {"value": 3, "label": "concise"}]}, {"id": "apt_ver6", "type": "mcq", "prompt": "Choose the word closest in meaning to MITIGATE.", "scale": "verbal", "key": 0, "options": [{"value": 0, "label": "Lessen"}, {"value": 1, "label": "Worsen"}, {"value": 2, "label": "Ignore"}, {"value": 3, "label": "Measure"}]}, {"id": "apt_ver7", "type": "mcq", "prompt": "''All shortlisted vendors are ISO certified. Vendor X is not ISO certified.'' What follows?", "scale": "verbal", "key": 3, "options": [{"value": 0, "label": "Vendor X is shortlisted"}, {"value": 1, "label": "Some shortlisted vendors are not certified"}, {"value": 2, "label": "Nothing follows"}, {"value": 3, "label": "Vendor X is not shortlisted"}]}, {"id": "apt_ver8", "type": "mcq", "prompt": "Choose the word opposite in meaning to FRUGAL.", "scale": "verbal", "key": 3, "options": [{"value": 0, "label": "Poor"}, {"value": 1, "label": "Careful"}, {"value": 2, "label": "Thrifty"}, {"value": 3, "label": "Extravagant"}]}]}, {"code": "abstract", "name": "Patterns", "time_limit_sec": 240, "items": [{"id": "apt_abs1", "type": "mcq", "prompt": "What comes next: 2, 5, 11, 20, 32, …", "scale": "abstract", "key": 0, "options": [{"value": 0, "label": "47"}, {"value": 1, "label": "46"}, {"value": 2, "label": "48"}, {"value": 3, "label": "62"}]}, {"id": "apt_abs2", "type": "mcq", "prompt": "What comes next: 2, 4, 6, 10, 16, …", "scale": "abstract", "key": 0, "options": [{"value": 0, "label": "26"}, {"value": 1, "label": "36"}, {"value": 2, "label": "27"}, {"value": 3, "label": "25"}]}, {"id": "apt_abs3", "type": "mcq", "prompt": "What comes next: 3, 7, 15, 31, 63, …", "scale": "abstract", "key": 0, "options": [{"value": 0, "label": "127"}, {"value": 1, "label": "128"}, {"value": 2, "label": "191"}, {"value": 3, "label": "126"}]}, {"id": "apt_abs4", "type": "mcq", "prompt": "What comes next: 18, 25, 23, 30, 28, …", "scale": "abstract", "key": 1, "options": [{"value": 0, "label": "36"}, {"value": 1, "label": "35"}, {"value": 2, "label": "34"}, {"value": 3, "label": "42"}]}, {"id": "apt_abs5", "type": "mcq", "prompt": "What comes next: A, D, G, J, M, …", "scale": "abstract", "key": 2, "options": [{"value": 0, "label": "Q"}, {"value": 1, "label": "R"}, {"value": 2, "label": "P"}, {"value": 3, "label": "O"}]}, {"id": "apt_abs6", "type": "mcq", "prompt": "What comes next: 3, 6, 12, 24, 48, …", "scale": "abstract", "key": 3, "options": [{"value": 0, "label": "95"}, {"value": 1, "label": "144"}, {"value": 2, "label": "97"}, {"value": 3, "label": "96"}]}, {"id": "apt_abs7", "type": "mcq", "prompt": "What comes next: 1, 4, 9, 16, 25, …", "scale": "abstract", "key": 1, "options": [{"value": 0, "label": "37"}, {"value": 1, "label": "36"}, {"value": 2, "label": "35"}, {"value": 3, "label": "47"}]}, {"id": "apt_abs8", "type": "mcq", "prompt": "Which number does not belong: 2, 3, 5, 7, 9, 11?", "scale": "abstract", "key": 3, "options": [{"value": 0, "label": "2"}, {"value": 1, "label": "11"}, {"value": 2, "label": "7"}, {"value": 3, "label": "9"}]}]}, {"code": "spatial", "name": "Shapes and space", "time_limit_sec": 240, "items": [{"id": "apt_spa1", "type": "mcq", "prompt": "A 4×4×4 cube painted on all faces is cut into 64 unit cubes. How many have exactly three painted faces?", "scale": "spatial", "key": 1, "options": [{"value": 0, "label": "24"}, {"value": 1, "label": "8"}, {"value": 2, "label": "12"}, {"value": 3, "label": "4"}]}, {"id": "apt_spa2", "type": "mcq", "prompt": "The same 64 unit cubes: how many have exactly one painted face?", "scale": "spatial", "key": 3, "options": [{"value": 0, "label": "36"}, {"value": 1, "label": "8"}, {"value": 2, "label": "16"}, {"value": 3, "label": "24"}]}, {"id": "apt_spa3", "type": "mcq", "prompt": "You walk 3 km north, then 4 km east. How far are you from the start in a straight line?", "scale": "spatial", "key": 0, "options": [{"value": 0, "label": "5 km"}, {"value": 1, "label": "7 km"}, {"value": 2, "label": "6 km"}, {"value": 3, "label": "1 km"}]}, {"id": "apt_spa4", "type": "mcq", "prompt": "You face south and turn 270° clockwise. Which way are you facing?", "scale": "spatial", "key": 0, "options": [{"value": 0, "label": "East"}, {"value": 1, "label": "South"}, {"value": 2, "label": "West"}, {"value": 3, "label": "North"}]}, {"id": "apt_spa5", "type": "mcq", "prompt": "What is the angle between the clock hands at 6:00?", "scale": "spatial", "key": 1, "options": [{"value": 0, "label": "90°"}, {"value": 1, "label": "180°"}, {"value": 2, "label": "120°"}, {"value": 3, "label": "0°"}]}, {"id": "apt_spa6", "type": "mcq", "prompt": "How many edges does a triangular prism have?", "scale": "spatial", "key": 0, "options": [{"value": 0, "label": "9"}, {"value": 1, "label": "5"}, {"value": 2, "label": "6"}, {"value": 3, "label": "12"}]}, {"id": "apt_spa7", "type": "mcq", "prompt": "On a map 1 cm stands for 5 km. Two towns are 7.5 cm apart on the map. How far apart are they?", "scale": "spatial", "key": 2, "options": [{"value": 0, "label": "75 km"}, {"value": 1, "label": "12.5 km"}, {"value": 2, "label": "37.5 km"}, {"value": 3, "label": "35.5 km"}]}, {"id": "apt_spa8", "type": "mcq", "prompt": "A rectangle is rolled up so that two opposite edges meet. Which shape does it make?", "scale": "spatial", "key": 1, "options": [{"value": 0, "label": "Cone"}, {"value": 1, "label": "Cylinder"}, {"value": 2, "label": "Sphere"}, {"value": 3, "label": "Pyramid"}]}]}, {"code": "logical", "name": "Reasoning", "time_limit_sec": 240, "items": [{"id": "apt_log1", "type": "mcq", "prompt": "All managers in the firm attended the training. Neha did not attend. Which must be true?", "scale": "logical", "key": 1, "options": [{"value": 0, "label": "Nothing follows"}, {"value": 1, "label": "Neha is not a manager in the firm"}, {"value": 2, "label": "Neha is a manager"}, {"value": 3, "label": "Some managers skipped the training"}]}, {"id": "apt_log2", "type": "mcq", "prompt": "Every project that overruns its budget is reviewed. Project K was reviewed. What follows?", "scale": "logical", "key": 2, "options": [{"value": 0, "label": "Only overrunning projects are reviewed, so K overran"}, {"value": 1, "label": "K overran its budget"}, {"value": 2, "label": "We cannot tell whether K overran its budget"}, {"value": 3, "label": "K stayed within budget"}]}, {"id": "apt_log3", "type": "mcq", "prompt": "Anil''s father is the only son of Mohan''s father. How is Mohan related to Anil?", "scale": "logical", "key": 2, "options": [{"value": 0, "label": "Grandfather"}, {"value": 1, "label": "Brother"}, {"value": 2, "label": "Father"}, {"value": 3, "label": "Uncle"}]}, {"id": "apt_log4", "type": "mcq", "prompt": "Some analysts are engineers. All engineers are graduates. Which must be true?", "scale": "logical", "key": 1, "options": [{"value": 0, "label": "All analysts are graduates"}, {"value": 1, "label": "Some analysts are graduates"}, {"value": 2, "label": "All graduates are engineers"}, {"value": 3, "label": "No analyst is a graduate"}]}, {"id": "apt_log5", "type": "mcq", "prompt": "What comes next: Monday, Wednesday, Saturday, Wednesday, …", "scale": "logical", "key": 0, "options": [{"value": 0, "label": "Monday"}, {"value": 1, "label": "Thursday"}, {"value": 2, "label": "Tuesday"}, {"value": 3, "label": "Sunday"}]}, {"id": "apt_log6", "type": "mcq", "prompt": "''Some A are B'' is true. Which statement could still be false?", "scale": "logical", "key": 0, "options": [{"value": 0, "label": "All A are B"}, {"value": 1, "label": "Some B are A"}, {"value": 2, "label": "It is not true that no A is B"}, {"value": 3, "label": "At least one A is B"}]}, {"id": "apt_log7", "type": "mcq", "prompt": "If the code for 1234 is 4321 and for 5678 is 8765, what is the code for 2468?", "scale": "logical", "key": 3, "options": [{"value": 0, "label": "4286"}, {"value": 1, "label": "6824"}, {"value": 2, "label": "2468"}, {"value": 3, "label": "8642"}]}, {"id": "apt_log8", "type": "mcq", "prompt": "Four tasks: B after A, C after B, and D before A. Which order is correct?", "scale": "logical", "key": 3, "options": [{"value": 0, "label": "A, B, C, D"}, {"value": 1, "label": "D, B, A, C"}, {"value": 2, "label": "A, D, B, C"}, {"value": 3, "label": "D, A, B, C"}]}]}]}'::jsonb,
   '{"method": "aptitude", "subtests": ["numerical", "verbal", "abstract", "spatial", "logical"], "bands": [[0, 25, "Low"], [25, 75, "Average"], [75, 90, "High"], [90, 101, "Very High"]]}'::jsonb,
   '{"13-15": {"numerical": {"mean": 4.4, "sd": 1.76}, "verbal": {"mean": 4.4, "sd": 1.76}, "abstract": {"mean": 4.4, "sd": 1.76}, "spatial": {"mean": 4.4, "sd": 1.76}, "logical": {"mean": 4.4, "sd": 1.76}}, "16-18": {"numerical": {"mean": 4.4, "sd": 1.76}, "verbal": {"mean": 4.4, "sd": 1.76}, "abstract": {"mean": 4.4, "sd": 1.76}, "spatial": {"mean": 4.4, "sd": 1.76}, "logical": {"mean": 4.4, "sd": 1.76}}, "19-22": {"numerical": {"mean": 4.4, "sd": 1.76}, "verbal": {"mean": 4.4, "sd": 1.76}, "abstract": {"mean": 4.4, "sd": 1.76}, "spatial": {"mean": 4.4, "sd": 1.76}, "logical": {"mean": 4.4, "sd": 1.76}}, "23+": {"numerical": {"mean": 4.4, "sd": 1.76}, "verbal": {"mean": 4.4, "sd": 1.76}, "abstract": {"mean": 4.4, "sd": 1.76}, "spatial": {"mean": 4.4, "sd": 1.76}, "logical": {"mean": 4.4, "sd": 1.76}}}'::jsonb, 20, true
