insert into public.instruments (code, name, version, track_variant, items, scoring_spec, norms, time_limit_min, is_active)
select 'bigfive', 'Personality (Big Five)', '0.2-original', 'adult',
   '{"sections": [{"code": "main", "name": "About me", "time_limit_sec": null, "items": [{"id": "bf_O1", "type": "likert5", "prompt": "I enjoy thinking about new ideas", "scale": "O", "reverse": false, "options": [{"value": 1, "label": "Disagree strongly"}, {"value": 2, "label": "Disagree a little"}, {"value": 3, "label": "Neutral"}, {"value": 4, "label": "Agree a little"}, {"value": 5, "label": "Agree strongly"}]}, {"id": "bf_C1", "type": "likert5", "prompt": "I keep my things organised", "scale": "C", "reverse": false, "options": [{"value": 1, "label": "Disagree strongly"}, {"value": 2, "label": "Disagree a little"}, {"value": 3, "label": "Neutral"}, {"value": 4, "label": "Agree a little"}, {"value": 5, "label": "Agree strongly"}]}, {"id": "bf_E1", "type": "likert5", "prompt": "I am outgoing and sociable", "scale": "E", "reverse": false, "options": [{"value": 1, "label": "Disagree strongly"}, {"value": 2, "label": "Disagree a little"}, {"value": 3, "label": "Neutral"}, {"value": 4, "label": "Agree a little"}, {"value": 5, "label": "Agree strongly"}]}, {"id": "bf_A1", "type": "likert5", "prompt": "I am considerate of others'' feelings", "scale": "A", "reverse": false, "options": [{"value": 1, "label": "Disagree strongly"}, {"value": 2, "label": "Disagree a little"}, {"value": 3, "label": "Neutral"}, {"value": 4, "label": "Agree a little"}, {"value": 5, "label": "Agree strongly"}]}, {"id": "bf_N1", "type": "likert5", "prompt": "I worry a lot", "scale": "N", "reverse": false, "options": [{"value": 1, "label": "Disagree strongly"}, {"value": 2, "label": "Disagree a little"}, {"value": 3, "label": "Neutral"}, {"value": 4, "label": "Agree a little"}, {"value": 5, "label": "Agree strongly"}]}, {"id": "bf_O2", "type": "likert5", "prompt": "I like art, music or literature", "scale": "O", "reverse": false, "options": [{"value": 1, "label": "Disagree strongly"}, {"value": 2, "label": "Disagree a little"}, {"value": 3, "label": "Neutral"}, {"value": 4, "label": "Agree a little"}, {"value": 5, "label": "Agree strongly"}]}, {"id": "bf_C2", "type": "likert5", "prompt": "I finish what I start", "scale": "C", "reverse": false, "options": [{"value": 1, "label": "Disagree strongly"}, {"value": 2, "label": "Disagree a little"}, {"value": 3, "label": "Neutral"}, {"value": 4, "label": "Agree a little"}, {"value": 5, "label": "Agree strongly"}]}, {"id": "bf_E2", "type": "likert5", "prompt": "I feel energised around people", "scale": "E", "reverse": false, "options": [{"value": 1, "label": "Disagree strongly"}, {"value": 2, "label": "Disagree a little"}, {"value": 3, "label": "Neutral"}, {"value": 4, "label": "Agree a little"}, {"value": 5, "label": "Agree strongly"}]}, {"id": "bf_A2", "type": "likert5", "prompt": "I trust people easily", "scale": "A", "reverse": false, "options": [{"value": 1, "label": "Disagree strongly"}, {"value": 2, "label": "Disagree a little"}, {"value": 3, "label": "Neutral"}, {"value": 4, "label": "Agree a little"}, {"value": 5, "label": "Agree strongly"}]}, {"id": "bf_N2", "type": "likert5", "prompt": "I get stressed easily", "scale": "N", "reverse": false, "options": [{"value": 1, "label": "Disagree strongly"}, {"value": 2, "label": "Disagree a little"}, {"value": 3, "label": "Neutral"}, {"value": 4, "label": "Agree a little"}, {"value": 5, "label": "Agree strongly"}]}, {"id": "bf_O3", "type": "likert5", "prompt": "I prefer routines to new experiences", "scale": "O", "reverse": true, "options": [{"value": 1, "label": "Disagree strongly"}, {"value": 2, "label": "Disagree a little"}, {"value": 3, "label": "Neutral"}, {"value": 4, "label": "Agree a little"}, {"value": 5, "label": "Agree strongly"}]}, {"id": "bf_C3", "type": "likert5", "prompt": "I often leave tasks to the last minute", "scale": "C", "reverse": true, "options": [{"value": 1, "label": "Disagree strongly"}, {"value": 2, "label": "Disagree a little"}, {"value": 3, "label": "Neutral"}, {"value": 4, "label": "Agree a little"}, {"value": 5, "label": "Agree strongl